# validate_document_fields.py\n# [SAME-SCENARIO] validates required structured fields and confidence scores\n\nfrom document_models import ValidationResult\n\ndef validate_document_fields(response: dict) -> ValidationResult:\n    required_fields = ['vendor', 'date', 'total', 'items']\n    missing = [field for field in required_fields if response.get(field) is None]\n    confidence_ok = response.get('confidence', 0.0) >= 0.8\n    valid = not missing and confidence_ok\n    message = f'Validation {'passed' if valid else 'failed'}: missing={missing}, confidence={response.get("confidence")}'\n    return ValidationResult(\n        is_valid=valid,\n        details={'missing_fields': missing, 'confidence_ok': confidence_ok, 'message': message}\n    )\n
